package com.newuniverse.nusmp.labyrinth.mega.lock;

import com.newuniverse.nusmp.labyrinth.mega.Room;
import com.newuniverse.nusmp.labyrinth.mega.RoomKind;
import com.newuniverse.nusmp.labyrinth.mega.Sector;
import com.newuniverse.nusmp.labyrinth.mega.gen.StairReach;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Why: the generator's check ({@link StairReach#problems}) judges a PLAN before it is placed; the game also has the SAVED sector (an old world, a repaired one, one
 * regenerated by an operator), and the owner's rule is that every placed room has a path to the stairs. This applies the same flood fill to a saved {@link Sector}: rooms are
 * the sector's rooms, doorways its saved edges, the arrival the first room of the floor model (the arrival stairwell) or the room that holds the saved arrival cell, and the
 * stairs the stairwells (the Landing for a sector of the old model). It is what {@code /multiverse mega lock reach} prints and what the {@code lock.escape} self-test runs over
 * every sector the CI server generated.
 */
public final class SectorReach {
    private SectorReach() {}

    /** The flood fill of a saved sector. Rooms are numbered by their position in {@code sector.rooms}. */
    public static StairReach.Report of(Sector s) {
        List<Room> rooms = s.rooms;
        Map<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < rooms.size(); i++) index.put(rooms.get(i).id, i);
        List<int[]> edges = new ArrayList<>();
        for (int[] e : s.edges) {
            Integer a = index.get(e[0]), b = index.get(e[1]);
            if (a != null && b != null) edges.add(new int[] {a, b});
        }
        List<Integer> stairs = new ArrayList<>();
        for (int i = 0; i < rooms.size(); i++) if (rooms.get(i).kind == RoomKind.STAIRWELL) stairs.add(i);
        int arrival = -1;
        if (s.arrival != null) for (int i = 0; i < rooms.size(); i++) if (rooms.get(i).contains(s.arrival)) arrival = i;
        if (arrival < 0) for (int i = 0; i < rooms.size(); i++) if (rooms.get(i).kind == RoomKind.STAIRWELL || rooms.get(i).kind == RoomKind.LANDING) {
            arrival = i;
            break;
        }
        if (arrival < 0 && !rooms.isEmpty()) arrival = 0;
        if (stairs.isEmpty()) for (int i = 0; i < rooms.size(); i++) if (rooms.get(i).kind == RoomKind.LANDING) stairs.add(i);
        if (stairs.isEmpty() && arrival >= 0) stairs.add(arrival);
        return StairReach.analyse(rooms.size(), edges, arrival, stairs);
    }

    /** The sentences for a report that is not fine (empty when it is). The room ids are the sector's own. */
    public static List<String> problems(Sector s) {
        List<String> out = new ArrayList<>();
        if (s.rooms.isEmpty() || s.state == Sector.State.GENERATING || s.state == Sector.State.FAILED) return out;
        StairReach.Report r = of(s);
        for (int i : r.cutOff()) out.add("room " + s.rooms.get(i).id + " (" + s.rooms.get(i).template + ") cannot be walked to from the arrival");
        for (int i : r.noStairs()) if (!r.cutOff().contains(i)) out.add("room " + s.rooms.get(i).id + " has no path to a stairwell");
        if (!r.stairsJoined()) out.add("a stairwell cannot be walked to from the arrival");
        return out;
    }
}
